SELECT `n`.`channel`, `t`.`key`, COUNT(*) AS sent, SUM(`n`.`read_at` IS NOT NULL) FROM `notification` `n` INNER JOIN `template` `t` ON `t`.`id`=`n`.`template_id` AND (`t`.`deleted_at` IS NULL) WHERE `n`.`created_at` >= '2026-10-03 00:00:00' AND `n`.`created_at` < '2026-10-10 00:00:00' AND `n`.`status` IN ('SENT','DELIVERED','BOUNCED','COMPLAINED') GROUP BY `t`.`key`, `n`.`channel` ORDER BY sent DESC, `t`.`key` ASC;
